def transform(grid):
    h, w = len(grid), len(grid[0])

    # A solid horizontal divider: keep the pattern above it.
    for r in range(h):
        color = grid[r][0]
        if color and all(x == color for x in grid[r]):
            return [[2 if x else 0 for x in row] for row in grid[:r]]

    # A solid vertical divider: retain positions occupied on both sides.
    for c in range(w):
        color = grid[0][c]
        if color and all(grid[r][c] == color for r in range(h)):
            width = min(c, w - c - 1)
            return [
                [
                    2 if grid[r][j] and grid[r][c + 1 + j] else 0
                    for j in range(width)
                ]
                for r in range(h)
            ]

    return [[0 for _ in row] for row in grid]
